D=[[3]*20 for _ in range(20)]
# vertical partition
for r in range(20): D[r][11]=9
# box rings including the 9 border, then alternating 2/9 inward
for r in range(4,11):
 for c in range(3,12):
  d=min(r-4,10-r,c-3,11-c)
  D[r][c]=9 if d%2==0 else 2
# bottom-left rectangle, palette from lower-left corner: 7,4
for r in range(11,20):
 for c in range(11):
  d=min(r-11,19-r,c,10-c)
  D[r][c]=7 if d%2==0 else 4
# right rectangle: palette from bottom-right corner: 6,7
for r in range(20):
 for c in range(12,20):
  d=min(r,19-r,c-12,19-c)
  D[r][c]=6 if d%2==0 else 7
print('\n'.join(' '.join(map(str,row)) for row in D))

